61	    SheetHeader,
62	    SheetTitle,
63	    SheetTrigger,
64	} from "@/shared/ui/sheet";
65	import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/shared/ui/tabs";
66	import { ScrollArea } from "@/shared/ui/scroll-area";
67	import { ProntaEntregaAnalytics } from "@/components/pronta-entrega/ProntaEntregaAnalytics";
68	import { cn } from "@/shared/lib/utils";
69	import { toast } from "sonner";
70	import { useAuth } from "@/hooks/useAuth";
71	import { useStore } from "@/shared/contexts/StoreContext";
72	import { BarChart3, LayoutDashboard, Store } from "lucide-react";
73	import { useMiaProntaEntregaActions } from '@/features/mia/model/hooks';
74	
75	// Lista pré-definida de produtos
76	const DEFAULT_PRODUCTS = [
77	    "Vulcão pistache", "Vulcão churros", "Vulcão brigadeiro", "Vulcão limão",
78	    "Naked P pistache", "Naked P chocolate", "Naked P casadinho",
79	    "Naked M pistache", "Naked M chocolate", "Naked M casadinho",
80	    "Naked G pistache", "Naked G chocolate", "Naked G Casadinho",
81	    "Dressed P pistache", "Dressed P chocolate", "Dressed P casadinho",
82	    "Dressed M pistache", "Dressed M chocolate", "Dressed M casadinho",
83	    "Dressed G pistache", "Dressed G chocolate", "Dressed G casadinho"
84	];
85	
86	// Tipo local baseado no DB
87	type ProntaEntregaItem = {
88	    id: string;
89	    created_at: string;
90	    product_name: string;
91	    quantity: number;
92	    entry_date: string; // date string YYYY-MM-DD
93	    validity_date?: string | null; // date string YYYY-MM-DD
94	    location: "congelado" | "resfriado" | "expositor";
95	    store_id: number | null;
96	    created_by: string | null;
97	};
98	
99	type LogItem = {
100	    id: string;
101	    created_at: string;
102	    user_email: string | null;
103	    action: string | null;
104	    product_name: string | null;
105	    details: any;
106	};
107	
108	const LOCATIONS = {
109	    congelado: {
110	        label: "Câmara Fria",
111	        icon: Snowflake,
112	        color: "text-zinc-900",
113	        bgHeader: "bg-zinc-900 shadow-lg shadow-zinc-900/20",
114	        border: "border-zinc-200 dark:border-zinc-800",
115	        glow: "shadow-zinc-500/20"
116	    },
117	    resfriado: {
118	        label: "Refrigeração",
119	        icon: ThermometerSnowflake,
120	        color: "text-sky-500",
121	        bgHeader: "bg-sky-500 shadow-lg shadow-sky-500/20",
122	        border: "border-sky-100 dark:border-sky-900/50",
123	        glow: "shadow-sky-500/20"
124	    },
125	    expositor: {
126	        label: "Expositora",
127	        icon: Monitor,
128	        color: "text-[#57715B]",
129	        bgHeader: "bg-[#57715B] shadow-lg shadow-[#57715B]/20",
130	        border: "border-[#57715B]/20",
131	        glow: "shadow-[#57715B]/20"
132	    },
133	};
134	
135	const getLocalTodayDate = todayLocalISO;
136	
137	export default function ProntaEntrega() {
138	    useMiaPageContext({
139	        description: 'Pronta Entrega — produtos prontos pra venda, organizados em geladeira/balcão/expositor com drag-and-drop entre seções e lojas.',
140	        natural_language_hints: '"mover X" = drag de uma seção pra outra; "transferir loja" = arraste entre colunas de lojas; "estoque PE" = visual atual; "novo lote" = botão Plus.',
141	        capabilities: ['mover_produto', 'transferir_loja', 'criar_lote', 'descartar_vencido'],
142	        destructive_actions: ['descartar', 'remover_lote'],
143	        primary_entity: 'pronta_entrega_item',
144	    });
145	    const { canViewProntaEntrega, isAdmin } = usePermissions();
146	    const { user } = useAuth();
147	    const { selectedStore, stores } = useStore();
148	    const [items, setItems] = useState<ProntaEntregaItem[]>([]);
149	    const [logs, setLogs] = useState<LogItem[]>([]);
150	    const [loading, setLoading] = useState(true);
151	    const [viewMode, setViewMode] = useState<"board" | "analytics">("board");
152	
153	    // Analytics specific store filter (for admins)
154	    const [analyticsStoreId, setAnalyticsStoreId] = useState<string>("current"); // "current", "all", or specific ID
155	
156	    // Mobile check
157	    const [isMobile, setIsMobile] = useState(false);
158	    useEffect(() => {
159	        const check = () => setIsMobile(window.innerWidth < 768);
160	        check();
161	        window.addEventListener('resize', check);
162	        return () => window.removeEventListener('resize', check);
163	    }, []);
164	
165	    // Modals State
166	    const [isCreateOpen, setIsCreateOpen] = useState(false);
167	    const [itemToDetail, setItemToDetail] = useState<ProntaEntregaItem | null>(null);
168	    const [consumeQty, setConsumeQty] = useState(1);
169	
170	    const [activeId, setActiveId] = useState<string | null>(null);
171	    const [search, setSearch] = useState("");
172	    const [showSuggestions, setShowSuggestions] = useState(false);
173	
174	
175	    // Form State
176	    const [form, setForm] = useState<{
177	        product_name: string;
178	        quantity: number;
179	        location: "congelado" | "resfriado" | "expositor";
180	        entry_date: string;
181	        validity_date: string;
182	    }>({
183	        product_name: "",
184	        quantity: 1,
185	        location: "congelado",
186	        entry_date: getLocalTodayDate(),
187	        validity_date: "",
188	    });
189	
190	    useEffect(() => {
191	        if (selectedStore) {
192	            fetchItems();
193	            fetchLogs();
194	            // Reset analytics store when global store changes (unless "all")
195	            if (analyticsStoreId === "current") {
196	                // re-fetch logic handled by dependency
197	            }
198	        }
199	    }, [selectedStore, analyticsStoreId, viewMode]);
200	
201	    const fetchItems = async () => {
202	        if (!selectedStore) return;
203	        setLoading(true);
204	
205	        let query = supabase
206	            .from("pronta_entrega_stock")
207	            .select("*")
208	            .order("created_at", { ascending: false });
209	
210	        // If in Analytics mode and "all" is selected, fetch everything (if admin)
211	        // Otherwise, stick to selectedStore or specific analytics store
212	        if (viewMode === "analytics" && isAdmin()) {
213	            if (analyticsStoreId !== "all") {
214	                const targetStore = analyticsStoreId === "current" ? selectedStore.id : Number(analyticsStoreId);
215	                query = query.eq("store_id", targetStore);
216	            }
217	        } else {
218	            query = query.eq("store_id", selectedStore.id);
219	        }
220	
221	        const { data, error } = await query;
222	
223	        if (error) {
224	            console.error("Erro ao buscar itens:", error);
225	            toast.error("Erro ao carregar estoque.");
226	        } else {
227	            setItems(data as ProntaEntregaItem[] || []);
228	        }
229	        setLoading(false);
230	    };
231	
232	    const fetchLogs = async () => {
233	        if (!selectedStore) return;
234	
235	        let query = supabase
236	            .from("pronta_entrega_logs")
237	            .select("*")
238	            .order("created_at", { ascending: false })
239	            .limit(1000);
240	
241	        // Same logic for logs
242	        if (viewMode === "analytics" && isAdmin()) {
243	            if (analyticsStoreId !== "all") {
244	                const targetStore = analyticsStoreId === "current" ? selectedStore.id : Number(analyticsStoreId);
245	                query = query.eq("store_id", targetStore);
246	            }
247	        } else {
248	            query = query.eq("store_id", selectedStore.id);
249	        }
250	
251	        const { data } = await query;
252	
253	        if (data) {
254	            setLogs(data as LogItem[]);
255	        }
256	    };
257	
258	    const logAction = async (action: string, productName: string, details: any) => {
259	        // Optimistic log update
260	        const newLog: LogItem = {
261	            id: generateId(),
262	            created_at: new Date().toISOString(),
263	            user_email: user?.email || 'Sistema',
264	            action,
265	            product_name: productName,
266	            details
267	        };
268	        setLogs(prev => [newLog, ...prev]);
269	
270	        await supabase.from("pronta_entrega_logs").insert({
271	            action,
272	            product_name: productName,
273	            user_email: user?.email,
274	            details,
275	            store_id: selectedStore?.id
276	        });
277	    };
278	
279	    const handleCreate = async () => {
280	        if (!form.product_name) {
281	            toast.error("Nome do produto é obrigatório.");
282	            return;
283	        }
284	
285	        try {
286	            const { data, error } = await supabase
287	                .from("pronta_entrega_stock")
288	                .insert({
289	                    product_name: form.product_name,
290	                    quantity: form.quantity,
291	                    location: form.location,
292	                    entry_date: form.entry_date,
293	                    validity_date: form.validity_date || null,
294	                    created_by: user?.email,
295	                    store_id: selectedStore?.id
296	                })
297	                .select()
298	                .single();
299	
300	            if (error) throw error;
301	
302	            setItems((prev) => [data as ProntaEntregaItem, ...prev]);
303	            logAction("Criou", form.product_name, { quantity: form.quantity, location: form.location });
304	
305	            setIsCreateOpen(false);
306	            toast.success("Item adicionado com sucesso!");
307	            setForm({
308	                product_name: "",
309	                quantity: 1,
310	                location: "congelado",
311	                entry_date: getLocalTodayDate(),
312	                validity_date: "",
313	            });
314	        } catch (error) {
315	            console.error("Erro ao criar item:", error);
316	            toast.error("Erro ao adicionar item.");
317	        }
318	    };
319	
320	    const handleConsume = async () => {
321	        if (!itemToDetail) return;
322	
323	        // Cada card é um produto único, então sempre removemos o item
324	        try {
325	            await supabase.from("pronta_entrega_stock").delete().eq("id", itemToDetail.id);
326	            setItems(prev => prev.filter(i => i.id !== itemToDetail.id));
327	            logAction("Saída/Venda", itemToDetail.product_name, { quantity: 1 });
328	
329	            toast.success("Saída/Venda registrada.");
330	            setItemToDetail(null);
331	            setConsumeQty(1);
332	        } catch (e) {
333	            console.error(e);
334	            toast.error("Erro ao registrar saída.");
335	        }
336	    };
337	
338	    const handleDelete = async (id: string, name: string) => {
339	        if (!confirm("Tem certeza que deseja remover este item?")) return;
340	
341	        const item = items.find(i => i.id === id);
342	        const qty = item ? item.quantity : 0;
343	
344	        try {
345	            const { error } = await supabase.from("pronta_entrega_stock").delete().eq("id", id);
346	            if (error) throw error;
347	            setItems((prev) => prev.filter((i) => i.id !== id));
348	            logAction("Deletou", name, { quantity: qty });
349	            toast.success("Item removido.");
350	            setItemToDetail(null); // Close if open
351	        } catch (error) {
352	            console.error("Erro ao remover:", error);
353	            toast.error("Erro ao remover item.");
354	        }
355	    };
356	
357	    // Drag and Drop Handlers
358	    const sensors = useSensors(
359	        useSensor(MouseSensor, { activationConstraint: { distance: 10 } }),
360	        useSensor(TouchSensor, { activationConstraint: { delay: 100, tolerance: 20 } })
361	    );
362	
363	    const onDragStart = (event: DragStartEvent) => {
364	        setActiveId(String(event.active.id));
365	    };
366	
367	    const onDragEnd = async (event: DragEndEvent) => {
368	        const { active, over } = event;
369	        setActiveId(null);
370	
371	        if (!over) return;
372	
373	        const activeItemId = String(active.id).replace(/-board$/, "");
374	        const overId = String(over.id);
375	        const newLocation = overId.replace(/-board$/, "") as "congelado" | "resfriado" | "expositor";
376	
377	        const item = items.find((i) => i.id === activeItemId);
378	        if (!item || item.location === newLocation) return;
379	
380	        const oldLocation = item.location;
381	
382	        // Optimistic Update
383	        setItems((prev) =>
384	            prev.map((i) => (i.id === activeItemId ? { ...i, location: newLocation } : i))
385	        );
386	
387	        try {
388	            const { error } = await supabase
389	                .from("pronta_entrega_stock")
390	                .update({ location: newLocation })
391	                .eq("id", activeItemId);
392	
393	            if (error) {
394	                throw error;
395	            }
396	            logAction("Moveu", item.product_name, { from: oldLocation, to: newLocation });
397	            toast.success(`Movido para ${LOCATIONS[newLocation].label}`);
398	        } catch (error) {
399	            console.error("Erro ao mover item:", error);
400	            toast.error("Erro ao atualizar localização.");
401	            fetchItems(); // Revert
402	        }
403	    };
404	
405	    const filteredItems = useMemo(() => {
406	        return items.filter(i => i.product_name.toLowerCase().includes(search.toLowerCase()));
407	    }, [items, search]);
408	
409	    const activeItem = activeId ? items.find((i) => i.id === activeId.replace(/-board$/, "")) : null;
410	
411	    const handleMove = async (item: ProntaEntregaItem, newLocation: "congelado" | "resfriado" | "expositor") => {
412	        const oldLocation = item.location;
413	        if (oldLocation === newLocation) return;
414	
415	        // Optimistic Update
416	        setItems((prev) =>
417	            prev.map((i) => (i.id === item.id ? { ...i, location: newLocation } : i))
418	        );
419	
420	        setItemToDetail(null); // Close modal
421	
422	        try {
423	            const { error } = await supabase
424	                .from("pronta_entrega_stock")
425	                .update({ location: newLocation })
426	                .eq("id", item.id);
427	
428	            if (error) throw error;
429	            logAction("Moveu", item.product_name, { from: oldLocation, to: newLocation });
430	            toast.success(`Movido para ${LOCATIONS[newLocation].label}`);
431	        } catch (error) {
432	            console.error("Erro ao mover:", error);
433	            toast.error("Erro ao mover item.");
434	            fetchItems(); // Revert
435	        }
436	    };
437	
438	    // MIA integration
439	    useMiaProntaEntregaActions({
440	        setViewMode,
441	        setSearch,
442	        setIsCreateOpen,
443	        setForm,
444	        setItemToDetail,
445	        setAnalyticsStoreId,
446	        items,
