15	 * ao admin filtrar problemas por dispositivo (ex: "todos os erros vindos de
16	 * tablets Android com USB dongle"). Roda em runtime — userAgent muda raro.
17	 */
18	function getDeviceContext() {
19	  if (typeof window === "undefined") return {};
20	  const nav = window.navigator;
21	  return {
22	    "device.user_agent": nav?.userAgent || "unknown",
23	    "device.platform": nav?.platform || "unknown",
24	    "device.lang": nav?.language || "unknown",
25	    "device.viewport": `${window.innerWidth}x${window.innerHeight}`,
26	    "device.is_secure_context": String(window.isSecureContext ?? "unknown"),
27	    "device.touch": String((nav?.maxTouchPoints ?? 0) > 0),
28	  };
