31	/**
32	 * Persiste evento de telemetria do scanner no Supabase pra admin ver agregado.
33	 * Fire-and-forget — não bloqueia o fluxo do scan se falhar.
34	 */
35	export async function logScannerEvent(payload: {
36	  evento: 'qr_scanned' | 'qr_rejected' | 'qr_duplicate' | 'camera_error';
37	  scan_mode: string;
38	  scan_uid?: string | null;
39	  scan_pid?: string | null;
40	  raw_len?: number | null;
41	  raw_preview?: string | null;
42	  raw_is_only_hex?: boolean | null;
43	  raw_is_odd_len?: boolean | null;
44	  erro_mensagem?: string | null;
45	}) {
46	  try {
47	    if (typeof window === "undefined" || typeof navigator === "undefined") return;
48	    const { data: { user } } = await supabase.auth.getUser();
49	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
50	    await (supabase.from("scanner_telemetry" as any) as any).insert({
51	      ...payload,
52	      usuario_id: user?.id ?? null,
53	      user_agent: navigator.userAgent || null,
54	      platform: navigator.platform || null,
55	      viewport: `${window.innerWidth}x${window.innerHeight}`,
56	      is_secure_ctx: window.isSecureContext ?? null,
57	      is_touch: (navigator.maxTouchPoints ?? 0) > 0,
58	      language: navigator.language || null,
59	    });
60	  } catch {
61	    // não impede fluxo do scan; falha é silenciosa
62	  }
63	}
