65	// ── Audio ──────────────────────────────────────────────────────────────────
66	export function playSuccessSound() {
67	  try {
68	    const Ctx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
69	    const ctx = new Ctx();
70	    const osc = ctx.createOscillator();
71	    const gain = ctx.createGain();
72	    osc.connect(gain);
73	    gain.connect(ctx.destination);
74	    osc.frequency.value = 800;
75	    osc.type = "sine";
76	    gain.gain.value = 0.1;
77	    osc.start();
78	    osc.stop(ctx.currentTime + 0.15);
79	  } catch { /* ignore */ }
80	}
