115	// ── Hex decoder + parse (anti ABNT2) ───────────────────────────────────────
116	function decodeHex(hex: string) {
117	  const bytes = new Uint8Array(hex.length / 2);
118	  for (let i = 0; i < hex.length; i += 2) bytes[i / 2] = parseInt(hex.substring(i, i + 2), 16);
119	  return new TextDecoder().decode(bytes);
120	}
121	
122	/**
123	 * Limpa lixo que scanners Bluetooth (especialmente em tablets Android) podem
124	 * inserir antes/depois do payload: replacement char (�), BOM, controles
125	 * ASCII, zero-width spaces, line/paragraph separators. Sem isso, um único
126	 * caractere inválido faz o parseQrData escolher o caminho errado e JSON.parse
127	 * explode com "Unexpected token �".
128	 */
129	export function sanitizeScanInput(raw: string): string {
130	  if (!raw) return raw;
131	  return raw
132	    // Replacement char (U+FFFD) + BOM (U+FEFF)
133	    .replace(/[\uFFFD\uFEFF]/g, "")
134	    // ASCII control codes (tab, CR, LF, ESC, NUL, etc.) — exceto espaço
135	    // eslint-disable-next-line no-control-regex
136	    .replace(/[\x00-\x08\x0B-\x1F\x7F]/g, "")
137	    // Invisible Unicode markers (zero-width, line/para separators, word joiner).
138	    // ATENÇÃO: U+2028 é terminator de linha em JS — sempre escape, nunca literal.
139	    .replace(/[\u200B-\u200F\u2028-\u202F\u2060-\u206F]/g, "")
140	    .trim();
141	}
