563	export function useEtiquetaScanner({
564	  enabled,
565	  onScan,
566	  onInvalid,
567	  onDuplicate,
568	  cameraElementId = "etiqueta-qr-reader",
569	  initialMode = "bluetooth",
570	}: UseEtiquetaScannerOptions) {
571	  const [scanMode, setScanMode] = useState<ScanMode>(initialMode);
572	  const [scanBuffer, setScanBuffer] = useState("");
