660	      return;
661	    }
662	    // Sucesso — log info-level pra agregar volume e detectar regressões
663	    wideInfo("scanner.qr_scanned", "QR decodificou com sucesso", {
664	      domain: "logistica",
665	      attributes: {
666	        ...getDeviceContext(),
667	        "scan.mode": scanMode,
668	        "scan.uid": payload.uid || "(sem uid)",
669	        "scan.pid": payload.pid,
670	        "raw.len": String(raw?.length ?? 0),
671	      },
672	    });
673	    void logScannerEvent({
674	      evento: 'qr_scanned',
675	      scan_mode: scanMode,
676	      scan_uid: payload.uid || null,
677	      scan_pid: payload.pid,
678	      raw_len: raw?.length ?? 0,
679	      // Persiste raw_preview também em sucesso pra diagnóstico em campo —
680	      // muitas leituras "qr_scanned" no Android Chrome 147 vem com pid OK
